<?php
try {
if(untrailingslashit(home_url())!=='http://mpcbc.local')throw new RuntimeException('Design A only.');
$admins=get_users(['role'=>'administrator','number'=>1]);wp_set_current_user($admins[0]->ID);$root='C:/Projects/mpcbc';
$compiledReport=json_decode(file_get_contents("$root/content-source/atomic-compile-report.json"),true);
foreach($compiledReport as $id=>$entry)if(isset($entry['error'])||!empty($entry['warnings']))throw new RuntimeException("Unresolved preflight issue $id");
$normalise=fn($text)=>trim(preg_replace('/\s+/u',' ',html_entity_decode(preg_replace('/<[^>]*>/', ' ', $text),ENT_QUOTES|ENT_HTML5,'UTF-8')));
$fragments=function($ns)use(&$fragments,$normalise){$out=[];foreach($ns as $n){$s=$n['settings']??[];$type=$n['widgetType']??'';foreach(['title','editor','text'] as $key)if(in_array($type,['heading','text-editor','button'],true)&&is_string($s[$key]??null))$out[]=$normalise($s[$key]);if($type==='icon-list')foreach($s['icon_list'] as $item)$out[]=$normalise($item['text']);if($type==='nested-tabs')foreach($s['tabs'] as $item)$out[]=$normalise($item['tab_title']);if($type==='nested-accordion')foreach($s['items'] as $item)$out[]=$normalise($item['item_title']);$out=array_merge($out,$fragments($n['elements']??[]));}return $out;};
$atomicText=function($ns)use(&$atomicText,$normalise){$out=[];foreach($ns as $n){foreach(['title','paragraph','text'] as $key){$v=$n['settings'][$key]??null;if(is_array($v))$v=$v['value']??'';if(is_string($v))$out[]=$normalise($v);}$out=array_merge($out,$atomicText($n['elements']??[]));}return $out;};
$sources=[];$trees=[];
foreach($compiledReport as $id=>$entry){$source=json_decode(file_get_contents("$root/content-source/before-atomic-conversion/$id.json"),true);$tree=json_decode(file_get_contents("$root/content-source/atomic-compiled/$id.json"),true);$haystack=implode(' ',$atomicText($tree));foreach($fragments($source['data']) as $fragment)if($fragment!==''&&!str_contains($haystack,$fragment))throw new RuntimeException("Text missing in $id: ".mb_substr($fragment,0,90));$sources[$id]=$source;$trees[$id]=$tree;}
$report=[];$mutator=Elementor\Core\Utils\Document\Document_Mutator::instance();
foreach($trees as $id=>$tree){$final=[];foreach($tree as $element){$final=$mutator->insert_subtree($final,'document',null,$element);if(is_wp_error($final))throw new RuntimeException($final->get_error_message());}
 $doc=Elementor\Plugin::$instance->documents->get($id);if(!$doc->save(['elements'=>$final,'settings'=>is_array($sources[$id]['settings'])?$sources[$id]['settings']:[]]))throw new RuntimeException("Save failed $id");
 $actual=json_decode(get_post_meta($id,'_elementor_data',true),true);$atomic=0;$legacy=0;$walk=function($ns)use(&$walk,&$atomic,&$legacy){foreach($ns as $n){$type=$n['widgetType']??$n['elType'];if(str_starts_with($type,'e-'))$atomic++;elseif($type==='shortcode')$legacy++;else throw new RuntimeException('Unexpected classic element: '.$type);$walk($n['elements']??[]);}};$walk($actual);
 $report[]=['id'=>$id,'title'=>get_the_title($id),'atomic_elements'=>$atomic,'fluent_form_embeds'=>$legacy,'source_text_preserved'=>true];echo "Saved $id: $atomic Atomic, $legacy form embeds.\n";
}
// Export the live native records for handoff; historical source builders are superseded.
$manifest=json_decode(file_get_contents("$root/content-source/language-build-result.json"),true);foreach($manifest as $p){$path="$root/elementor/{$p['locale']}-{$p['topic']}.json";if(!file_exists($path))continue;$exp=json_decode(file_get_contents($path),true);$exp['content']=json_decode(get_post_meta($p['id'],'_elementor_data',true),true);file_put_contents($path,wp_json_encode($exp,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));if($p['locale']==='en')file_put_contents("$root/elementor/{$p['topic']}-content-filled.json",wp_json_encode($exp,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}
foreach([21=>'home-content-filled.json',16=>'footer-content-filled.json',17=>'welcome.json',18=>'prayer.json'] as $id=>$file){$path="$root/elementor/$file";$exp=file_exists($path)?json_decode(file_get_contents($path),true):['version'=>'0.4','title'=>get_the_title($id),'type'=>'page','page_settings'=>$sources[$id]['settings']];$exp['content']=json_decode(get_post_meta($id,'_elementor_data',true),true);file_put_contents($path,wp_json_encode($exp,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));if($id===21){$exp['content']=[$exp['content'][0]];file_put_contents("$root/elementor/home-hero.json",wp_json_encode($exp,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}}
Elementor\Plugin::$instance->files_manager->clear_cache();file_put_contents("$root/content-source/atomic-conversion-result.json",wp_json_encode(['pages'=>$report,'mcp_connection_enabled'=>false,'exception'=>'Four shortcode placements for three existing Fluent Forms; Elementor Free has no Atomic shortcode.'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));echo 'All compiled documents applied; native text preserved.';
}catch(Throwable $e){fwrite(STDERR,$e->getMessage());exit(1);}

